class Action(object):
    __slots__ = ['action', 'state', 'prod']

    def __init__(self, action, state=None, prod=None):
        self.action = action
        self.state = state
        self.prod = prod

    def __str__(self):
        ac = {0: 'SHIFT', 1: 'REDUCE', 2: 'ACCEPT'}.get(self.action)
        if self.action == 0:
            p = self.state.state_id
        elif self.action == 1:
            p = self.prod.prod_id
        else:
            p = ''
        return '%s%s' % (ac, ':%d' % p if p else '')
